2	// Runs the machine's installed ffmpeg (GPU-accelerated when available),
3	// so it is far faster than the in-browser WebAssembly build.
4	//
5	// Pure Node (no dependencies). Binds to 127.0.0.1 only — local use.
6	//
7	//   node server.mjs            # port 5060
8	//   PORT=5070 node server.mjs
9	
10	import http from 'node:http';
11	import { spawn } from 'node:child_process';
12	import { randomUUID } from 'node:crypto';
13	import { createWriteStream, createReadStream, promises as fs } from 'node:fs';
14	import os from 'node:os';
15	import path from 'node:path';
16	import { fileURLToPath } from 'node:url';
17	
18	const __dirname = path.dirname(fileURLToPath(import.meta.url));
19	const PUBLIC = path.join(__dirname, 'public');
20	const TMP = path.join(os.tmpdir(), 'svc-jobs');
21	const PORT = Number(process.env.PORT) || 5060;
22	
23	await fs.mkdir(TMP, { recursive: true });
24	
25	// ---------------------------------------------------------------------------
26	// Quality / encoder configuration
27	// ---------------------------------------------------------------------------
28	const LEVELS = ['quality', 'high', 'small', 'tiny'];
29	
30	const DEDUPE = {
31	  off:        null,
32	  gentle:     'mpdecimate=hi=512:lo=320:frac=0.33',
33	  normal:     'mpdecimate=hi=768:lo=320:frac=0.33',
34	  aggressive: 'mpdecimate=hi=1280:lo=512:frac=0.2',
35	};
36	
37	// Quality numbers per level, per encoder family (lower = better/bigger).
38	const Q = {
39	  x264: { quality: 18, high: 22, small: 26, tiny: 30 },
40	  x265: { quality: 22, high: 26, small: 30, tiny: 34 },
41	  nv:   { quality: 19, high: 24, small: 29, tiny: 33 },
42	  qsv:  { quality: 20, high: 25, small: 30, tiny: 34 },
43	  amf:  { quality: 20, high: 25, small: 30, tiny: 34 },
44	};
45	
46	// Raw encoders we probe for hardware support.
47	const RAW_ENCODERS = ['hevc_nvenc', 'h264_nvenc', 'hevc_qsv', 'h264_qsv',
48	                      'hevc_amf', 'h264_amf', 'libx265', 'libx264'];
49	
50	// GPU encoder argument builder (tuned for SPEED).
51	function gpuArgs(enc, level) {
52	  if (enc.endsWith('nvenc')) return ['-c:v', enc, '-preset', 'p4', '-rc', 'vbr', '-cq', String(Q.nv[level]), '-tune', 'hq'];
53	  if (enc.endsWith('qsv'))   return ['-c:v', enc, '-preset', 'veryfast', '-global_quality', String(Q.qsv[level])];
54	  return ['-c:v', enc, '-rc', 'cqp', '-qp_i', String(Q.amf[level]), '-qp_p', String(Q.amf[level]), '-quality', 'speed'];
55	}
56	
57	function pickGpu(available) {
58	  // prefer HEVC, then H.264; vendor order NVIDIA, Intel, AMD
59	  return ['hevc_nvenc', 'hevc_qsv', 'hevc_amf', 'h264_nvenc', 'h264_qsv', 'h264_amf']
60	    .find(e => available[e]) || null;
61	}
62	
63	// Build the user-facing SPEED profiles from whatever encoders actually work.
64	function buildProfiles(available) {
65	  const profiles = [];
66	  const gpu = pickGpu(available);
67	  if (gpu) {
68	    const vendor = gpu.includes('nvenc') ? 'NVIDIA' : gpu.includes('qsv') ? 'Intel' : 'AMD';
69	    const codec = gpu.startsWith('hevc') ? 'H.265' : 'H.264';
70	    profiles.push({ id: 'gpu', label: `🚀 Fastest — GPU (${vendor} ${codec})`, codec: gpu, build: l => gpuArgs(gpu, l) });
71	  }
72	  if (available.libx264) {
73	    profiles.push({ id: 'h264fast', label: '⚡ Fastest — H.264 (CPU)', codec: 'libx264',
74	      build: l => ['-c:v', 'libx264', '-preset', 'veryfast', '-crf', String(Q.x264[l])] });
75	    profiles.push({ id: 'h264bal', label: '⚖ Balanced — H.264 (CPU)', codec: 'libx264',
76	      build: l => ['-c:v', 'libx264', '-preset', 'fast', '-crf', String(Q.x264[l])] });
77	  }
78	  if (available.libx265) {
79	    profiles.push({ id: 'h265small', label: '🗜 Smallest — H.265 (CPU, slower)', codec: 'libx265',
80	      build: l => ['-c:v', 'libx265', '-preset', 'medium', '-crf', String(Q.x265[l])] });
81	  }
82	  return profiles;
83	}
84	
85	// ---------------------------------------------------------------------------
86	// Probe which encoders actually work on THIS hardware (build support != GPU
87	// present). Each gets a 1-frame test encode.
88	// ---------------------------------------------------------------------------
89	function probeEncoder(enc) {
90	  return new Promise(resolve => {
91	    let p;
92	    try {
93	      p = spawn('ffmpeg', ['-hide_banner', '-loglevel', 'error',
94	        '-f', 'lavfi', '-i', 'nullsrc=s=320x240:d=0.1', '-frames:v', '1',
95	        '-c:v', enc, '-f', 'null', '-']);
96	    } catch { return resolve(false); }
97	    p.on('error', () => resolve(false));
98	    p.on('close', code => resolve(code === 0));
99	  });
100	}
101	
102	let CAPS = null;   // { available, menu:[{id,label}], recommended, profiles:Map }
103	async function detectCaps() {
104	  const results = await Promise.all(RAW_ENCODERS.map(probeEncoder));
105	  const available = {};
106	  RAW_ENCODERS.forEach((id, i) => { available[id] = results[i]; });
107	  const profs = buildProfiles(available);
108	  const profilesById = new Map(profs.map(p => [p.id, p]));
109	  const menu = profs.map(p => ({ id: p.id, label: p.label }));
110	  // recommend the fastest option: GPU if present, else fast H.264
111	  const recommended = (profs.find(p => p.id === 'gpu') ||
112	                       profs.find(p => p.id === 'h264fast') || profs[0])?.id;
113	  CAPS = { available, menu, recommended, profiles: profilesById };
114	  return CAPS;
115	}
116	
117	// ---------------------------------------------------------------------------
118	// ffprobe helpers
119	// ---------------------------------------------------------------------------
120	function ffprobe(args) {
121	  return new Promise(resolve => {
122	    const p = spawn('ffprobe', args);
123	    let out = '';
124	    p.stdout.on('data', d => out += d);
125	    p.on('error', () => resolve(''));
126	    p.on('close', () => resolve(out.trim()));
127	  });
128	}
129	async function probeInput(file) {
130	  const dur = parseFloat(await ffprobe(['-v', 'error', '-show_entries', 'format=duration',
131	    '-of', 'csv=p=0', file])) || 0;
132	  let frames = parseInt(await ffprobe(['-v', 'error', '-select_streams', 'v:0',
133	    '-show_entries', 'stream=nb_frames', '-of', 'csv=p=0', file]), 10);
134	  if (!Number.isFinite(frames) || frames <= 0) frames = 0;
135	  return { duration: dur, frames };
136	}
137	
138	// ---------------------------------------------------------------------------
139	// Jobs
140	// ---------------------------------------------------------------------------
141	const jobs = new Map();   // id -> { input, output, opts, name, ... }
142	
143	function buildFfmpegArgs(job) {
144	  const { input, output, opts } = job;
145	  const filters = [];
146	  if (opts.dedupe !== 'off' && DEDUPE[opts.dedupe]) filters.push(DEDUPE[opts.dedupe]);
147	  filters.push('format=yuv420p');
148	  const vf = filters.join(',');
149	
150	  const profile = CAPS.profiles.get(opts.encoder) || CAPS.profiles.get(CAPS.recommended);
151	  job.encoderUsed = profile.codec;
152	  const encArgs = profile.build(opts.level).map(String);
153	
154	  return [
155	    '-y', '-hide_banner', '-loglevel', 'error', '-nostats',
156	    '-i', input,
157	    '-vf', vf,
158	    '-fps_mode', 'vfr',
159	    ...encArgs,
160	    '-pix_fmt', 'yuv420p',
161	    '-c:a', 'aac', '-b:a', '128k',
162	    '-movflags', '+faststart',
163	    '-progress', 'pipe:1',
164	    output,
165	  ];
166	}
167	
168	function runJob(job, onEvent) {
169	  const args = buildFfmpegArgs(job);
170	  job.proc = spawn('ffmpeg', args);
171	  let stderr = '';
172	  let buf = '';
173	  let lastFrame = 0;
174	
175	  job.proc.stdout.on('data', chunk => {
176	    buf += chunk.toString();
177	    const lines = buf.split('\n');
178	    buf = lines.pop();
179	    let progressed = false, ended = false, secs = 0;
180	    for (const line of lines) {
181	      const [k, v] = line.split('=');
182	      if (k === 'frame') { lastFrame = parseInt(v, 10) || lastFrame; progressed = true; }
183	      else if (k === 'out_time_us') { secs = (parseInt(v, 10) || 0) / 1e6; progressed = true; }
184	      else if (k === 'progress' && v === 'end') ended = true;
185	    }
186	    if (progressed) {
187	      const pct = job.duration > 0 ? Math.min(99, (secs / job.duration) * 100) : null;
188	      onEvent({ type: 'progress', percent: pct, seconds: secs, frame: lastFrame });
189	    }
190	    if (ended) job.outFrames = lastFrame;
191	  });
192	
193	  job.proc.stderr.on('data', d => { stderr += d; });
194	
195	  job.proc.on('error', err => onEvent({ type: 'error', message: 'ffmpeg failed to start: ' + err.message }));
196	
197	  job.proc.on('close', async code => {
198	    if (code !== 0) {
199	      onEvent({ type: 'error', message: (stderr.trim().split('\n').slice(-3).join(' ') || `ffmpeg exited ${code}`) });
200	      return;
201	    }
202	    let after = 0;
203	    try { after = (await fs.stat(job.output)).size; } catch {}
204	    job.done = true;
205	    onEvent({
206	      type: 'done',
207	      before: job.inputSize,
208	      after,
209	      saved: job.inputSize > 0 ? (100 * (job.inputSize - after) / job.inputSize) : 0,
210	      srcFrames: job.frames,
211	      outFrames: job.outFrames || lastFrame,
212	      dedupe: job.opts.dedupe,
213	      encoder: job.encoderUsed,
214	      downloadUrl: `/jobs/${job.id}/file`,
215	    });
216	  });
217	}
218	
219	async function cleanupJob(id) {
220	  const job = jobs.get(id);
221	  if (!job) return;
222	  try { job.proc?.kill('SIGKILL'); } catch {}
223	  for (const f of [job.input, job.output]) { try { await fs.unlink(f); } catch {} }
224	  jobs.delete(id);
225	}
226	
227	// ---------------------------------------------------------------------------
228	// HTTP
229	// ---------------------------------------------------------------------------
230	const MIME = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript', '.css': 'text/css', '.mp4': 'video/mp4' };
231	
232	function sendJSON(res, code, obj) {
233	  const body = JSON.stringify(obj);
234	  res.writeHead(code, { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body) });
235	  res.end(body);
236	}
237	
238	async function serveStatic(res, urlPath) {
239	  let rel = urlPath === '/' ? '/index.html' : urlPath;
240	  const file = path.join(PUBLIC, path.normalize(rel).replace(/^(\.\.[\/\\])+/, ''));
241	  if (!file.startsWith(PUBLIC)) { res.writeHead(403); return res.end('forbidden'); }
242	  try {
243	    const data = await fs.readFile(file);
244	    res.writeHead(200, { 'Content-Type': MIME[path.extname(file)] || 'application/octet-stream' });
245	    res.end(data);
246	  } catch {
247	    res.writeHead(404); res.end('not found');
248	  }
249	}
250	
251	const server = http.createServer(async (req, res) => {
252	  const url = new URL(req.url, `http://localhost:${PORT}`);
253	  const p = url.pathname;
254	
255	  // --- capabilities ---
256	  if (req.method === 'GET' && p === '/capabilities') {
257	    return sendJSON(res, 200, CAPS || await detectCaps());
258	  }
259	
260	  // --- upload + create job:  POST /jobs?name=..&level=..&dedupe=..&encoder=.. (raw body = file) ---
261	  if (req.method === 'POST' && p === '/jobs') {
262	    const id = randomUUID();
263	    const name = url.searchParams.get('name') || 'video.mp4';
264	    const opts = {
265	      level:   LEVELS.includes(url.searchParams.get('level')) ? url.searchParams.get('level') : 'high',
266	      dedupe:  DEDUPE[url.searchParams.get('dedupe')] !== undefined ? url.searchParams.get('dedupe') : 'normal',
267	      encoder: url.searchParams.get('encoder') || CAPS?.recommended,
268	    };
269	    const ext = (path.extname(name) || '.mp4').toLowerCase();
270	    const input = path.join(TMP, `${id}-in${ext}`);
271	    const output = path.join(TMP, `${id}-out.mp4`);
272	
273	    const ws = createWriteStream(input);
274	    req.pipe(ws);
275	    ws.on('error', () => sendJSON(res, 500, { error: 'upload write failed' }));
276	    ws.on('finish', async () => {
277	      let inputSize = 0;
278	      try { inputSize = (await fs.stat(input)).size; } catch {}
279	      const { duration, frames } = await probeInput(input);
280	      jobs.set(id, { id, input, output, opts, name, inputSize, duration, frames });
281	      sendJSON(res, 200, { id, inputSize, duration, frames });
282	    });
283	    return;
284	  }
285	
286	  // --- progress stream + start:  GET /jobs/:id/events (SSE) ---
287	  let m = p.match(/^\/jobs\/([\w-]+)\/events$/);
288	  if (req.method === 'GET' && m) {
289	    const job = jobs.get(m[1]);
290	    if (!job) { res.writeHead(404); return res.end('no job'); }
291	    res.writeHead(200, {
292	      'Content-Type': 'text/event-stream',
293	      'Cache-Control': 'no-cache',
294	      'Connection': 'keep-alive',
295	    });
296	    const send = obj => res.write(`data: ${JSON.stringify(obj)}\n\n`);
297	    send({ type: 'start', duration: job.duration, frames: job.frames, inputSize: job.inputSize });
298	    runJob(job, ev => {
299	      send(ev);
300	      if (ev.type === 'done' || ev.type === 'error') res.end();
301	    });
302	    req.on('close', () => { if (!job.done) cleanupJob(job.id); });
303	    return;
304	  }
305	
306	  // --- download result:  GET /jobs/:id/file ---
307	  m = p.match(/^\/jobs\/([\w-]+)\/file$/);
308	  if (req.method === 'GET' && m) {
309	    const job = jobs.get(m[1]);
310	    if (!job || !job.done) { res.writeHead(404); return res.end('not ready'); }
311	    const dlName = job.name.replace(/\.[^.]+$/, '') + '.compressed.mp4';
312	    res.writeHead(200, {
313	      'Content-Type': 'video/mp4',
314	      'Content-Disposition': `attachment; filename="${dlName}"`,
315	    });
316	    const rs = createReadStream(job.output);
317	    rs.pipe(res);
318	    rs.on('end', () => setTimeout(() => cleanupJob(job.id), 60_000)); // keep briefly for re-download
319	    rs.on('error', () => { res.destroy(); });
320	    return;
321	  }
322	
323	  // --- static frontend ---
324	  if (req.method === 'GET') return serveStatic(res, p);
325	
326	  res.writeHead(405); res.end('method not allowed');
327	});
328	
329	await detectCaps();
330	// Bind on all local interfaces (dual-stack) so both http://localhost (IPv6 ::1)
331	// and http://127.0.0.1 (IPv4) reach it regardless of how the browser resolves.
332	server.listen(PORT, () => {
333	  const avail = Object.entries(CAPS.available).filter(([, v]) => v).map(([k]) => k);
334	  console.log(`Smart Video Compressor (native) running at http://localhost:${PORT}`);
335	  console.log(`Working encoders: ${avail.join(', ') || 'none?!'}`);
336	  console.log(`Recommended: ${CAPS.recommended}`);
337	  // Open the browser only once we're actually listening (set by the launcher).
338	  if (process.env.OPEN_BROWSER) {
339	    const url = `http://127.0.0.1:${PORT}/`;
340	    const cmd = process.platform === 'win32' ? ['cmd', ['/c', 'start', '', url]]
341	              : process.platform === 'darwin' ? ['open', [url]]
342	              : ['xdg-open', [url]];
343	    try { spawn(cmd[0], cmd[1], { detached: true, stdio: 'ignore' }).unref(); } catch {}
344	  }
345	});
346

